(function() {
    var cdnList = [
        'https://lib.baomitu.com/jquery/3.6.0/jquery.min.js',
        'https://cdn.bootcdn.net/ajax/libs/jquery/3.6.0/jquery.min.js',
        'https://cdnjs.cloudflare.com/ajax/libs/jquery/3.6.0/jquery.min.js',
        'https://unpkg.com/jquery@3.6.0/dist/jquery.min.js'
    ];
    var loaded = false, timer;

    function done() {
        if (loaded || typeof window.jQuery === 'undefined') return;
        loaded = true;
        clearTimeout(timer);
        console.log('jQuery loaded');
        document.dispatchEvent(new Event('jQueryReady'));
        if (typeof window.jQueryReadyCallback === 'function') window.jQueryReadyCallback(window.jQuery);
    }

    if (typeof window.jQuery !== 'undefined') return done();

    cdnList.forEach(function(src) {
        var s = document.createElement('script');
        s.src = src;
        s.onload = done;
        document.head.appendChild(s);
    });

    timer = setTimeout(function() {
        if (!loaded && typeof window.jQuery === 'undefined') {
            var s = document.createElement('script');
            s.src = 'jquery.min-3.6.0.js';
            s.onload = done;
            document.head.appendChild(s);
            setTimeout(function() {
                if (!loaded && typeof window.jQuery === 'undefined') console.error('jQuery load failed');
            }, 3000);
        }
    }, 5000);

    window.jQueryReady = function(cb) {
        if (typeof window.jQuery !== 'undefined') cb(window.jQuery);
        else document.addEventListener('jQueryReady', function() { cb(window.jQuery); }, { once: true });
    };
})();
